export interface CountrySeed {
  id: string;
  nome: string;
  flag: string;
  regiao: string;
  lat?: number;
  lon?: number;
  iso?: number;
  pop: number;
  gdp: number;
  crescimento: number;
  inflacao: number;
  desemprego?: number;
  gini: number;
  divida: number;
  urbano: number;
  idade: number;
  fertilidade: number;
  vida: number;
  setores: Sectores;
  recurso: 'petroleo' | 'gas' | 'minerais' | 'alimento' | 'nenhum';
  indeRec: number;
  abertura: number;
  educ: number;
  saude: number;
  infra: number;
  felicidade: number;
  relig: number;
  regime: 'democracia' | 'híbrido' | 'autoritário';
  democracia: number;
  ideo: [number, number];
  expansionista?: boolean;
  lider?: string;
  militar: Partial<Militar>;
  eleicao?: number;
}

export const POLITICA = (p: Partial<Policies> = {}): Policies => ({ ...POLITICAS_BASE, ...p } as Policies);
export const TOGGLES = (t: Partial<Toggles> = {}): Toggles => ({
  drogaLegal: false, controleArmas: true, penaMorte: false, conscricao: false,
  ambicaoNuclear: false, bancosPublicos: false, censura: false, ...t,
});

const milFeito = (m: Partial<Militar>): Militar => ({
  ativo: 100, reserva: 50, orcamento: 10, tecnologia: 0.5, prontidao: 0.7, nuclear: false, ...m,
});

const IDEOLOGIA = (e: number, s: number): Ideology => ({ econ: e, social: s });

