export const cp = (a: Partial<CountrySeed> & { id: string; nome: string; flag: string }): CountrySeed => {
  const c = COORDS[a.id] ?? [0, 0, 0];
  const m = a.militar ?? {};
  return {
    regiao: 'Varia', pop: 15, gdp: 100, crescimento: 2.5, inflacao: 4, desemprego: 6, gini: 0.37,
    divida: 50, urbano: 0.6, idade: 28, fertilidade: 2.4, vida: 70, setores: { agricultura: 0.2, industria: 0.25, servicos: 0.55 },
    recurso: 'nenhum', indeRec: 0.3, abertura: 50, educ: 0.5, saude: 0.55, infra: 50, felicidade: 60,
    relig: 0.6, regime: 'híbrido', democracia: 0.5, ideo: [0, 0.1], militar: m,
    lat: a.lat ?? c[0], lon: a.lon ?? c[1], iso: a.iso ?? c[2], ...a,
  } as CountrySeed;
};

